function usePointsPricing(): PricingSnapshot {
  const [pricing, setPricing] = useState<PricingSnapshot>(() => buildPricingSnapshot());
  useEffect(() => {
    let active = true;
    fetch('/api/pricing')
      .then(res => (res.ok ? res.json() : null))
      .then(data => {
        if (active && data?.pricing) setPricing(data.pricing);
      })
      .catch(() => {});
    return () => {
      active = false;
    };
  }, []);
  return pricing;
}

