  const [mathActiveTab, setMathActiveTab] = useState<'calc' | 'arabic' | 'english' | 'advanced'>('calc');

  // Decluttered Composer Auxiliary Tools Tray State
  const [showComposerTools, setShowComposerTools] = useState<boolean>(false);
  const [plusMenuPlacement, setPlusMenuPlacement] = useState<{ up: boolean; maxHeight: number }>({ up: true, maxHeight: 540 });

  // Smart Study Notebook Search & Category Filters
  const [notebookSearchQuery, setNotebookSearchQuery] = useState<string>('');
  const [notebookCategoryFilter, setNotebookCategoryFilter] = useState<'all' | 'formula' | 'definition' | 'solution'>('all');

  // Stream Resilience
  const [lastFailedUserQuery, setLastFailedUserQuery] = useState<{ text: string; image?: any } | null>(null);

  // Flashcards Lesson Picker State
  const [selectedFlashcardLesson, setSelectedFlashcardLesson] = useState<any | null>(null);
  const [flashcardLessonTab, setFlashcardLessonTab] = useState<'curriculum' | 'custom'>('curriculum');

  // Kashier Payment & Subscription States
  const [subscribingPlan, setSubscribingPlan] = useState<string | null>(null);
  const [paymentSuccessData, setPaymentSuccessData] = useState<{
    planTitle: string;
    amount: number;
    bonusCoins: number;
  } | null>(null);
  const [paymentErrorToast, setPaymentErrorToast] = useState<string | null>(null);

  const isUserSubscribed = Boolean(
    user &&
    user.plan_type &&
    user.plan_type !== 'free' &&
    (user.subscription_status === 'active' || !user.subscription_status) &&
    (!user.subscription_end_date || new Date(user.subscription_end_date).getTime() > Date.now())
  );

  const planDurationDays = (user?.plan_type === 'pro_3m' || user?.plan_type === 'max')
    ? 90
    : (user?.plan_type === 'pro_2m' ? 60 : 30);

  const subscriptionStartMs = user?.subscription_start_date
    ? new Date(user.subscription_start_date).getTime()
    : (user?.created_at ? new Date(user.created_at).getTime() : Date.now());

  let effectiveEndMs: number | null = null;
  if (user?.subscription_end_date) {
    const rawEndMs = new Date(user.subscription_end_date).getTime();
    const spanDays = subscriptionStartMs > 0 ? Math.round((rawEndMs - subscriptionStartMs) / (24 * 60 * 60 * 1000)) : 0;
    if (planDurationDays > 30 && spanDays > 0 && spanDays <= 35) {
      effectiveEndMs = subscriptionStartMs + planDurationDays * 24 * 60 * 60 * 1000;
    } else {
      effectiveEndMs = rawEndMs;
    }
  } else if (isUserSubscribed) {
    effectiveEndMs = subscriptionStartMs + planDurationDays * 24 * 60 * 60 * 1000;
  }

  const remainingDays = effectiveEndMs
    ? Math.max(0, Math.ceil((effectiveEndMs - Date.now()) / (1000 * 60 * 60 * 24)))
    : (isUserSubscribed ? planDurationDays : 0);

  const formatRemainingSubscription = (days: number): string => {
    if (days <= 0) return 'انتهت مدة الاشتراك';
    if (days === 1) return 'يوم واحد متبقٍ';
    if (days === 2) return 'يومان متبقيان';
    if (days >= 3 && days <= 10) return `${days} أيام متبقية`;
    if (days >= 75) return `3 أشهر (${days} يوماً متبقياً)`;
    if (days >= 45) return `شهران (${days} يوماً متبقياً)`;
    if (days >= 20) return `شهر واحد (${days} يوماً متبقياً)`;
    return `${days} يوماً متبقياً`;
  };

  const handleSubscribe = async (planId: string) => {
    if (!user || !token) {
      setAuthTab('login');
      setShowAuthModal(true);
      return;
    }

    if (isUserSubscribed) {
      setPaymentErrorToast('لديك باقة اشتراك نشطة وسارية بالفعل. لا يمكن الاشتراك في باقة جديدة حتى انتهاء اشتراكك الحالي.');
      setTimeout(() => setPaymentErrorToast(null), 5000);
      return;
    }

    setSubscribingPlan(planId);
    try {
      const res = await fetch('/api/payment/kashier/initialize', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ plan_id: planId })
      });

      const data = await res.json();
      if (!res.ok || !data.success) {
        throw new Error(data.error || 'فشل تجهيز طلب الدفع');
      }

      const order = data.order;
      const redirectUrl = `https://checkout.kashier.io/?merchantId=${order.merchantId}&orderId=${order.orderId}&amount=${order.amount}&currency=${order.currency}&hash=${order.hash}&mode=${order.mode}&merchantRedirect=${encodeURIComponent(order.merchantRedirect)}&serverWebhook=${encodeURIComponent(order.serverWebhook)}&allowedMethods=${encodeURIComponent(order.allowedMethods)}&display=ar`;

      window.location.href = redirectUrl;
    } catch (err: any) {
      console.error('Subscription error:', err);
      setPaymentErrorToast(err.message || 'حدث خطأ أثناء بدء عملية الدفع عبر كاشير.');
      setTimeout(() => setPaymentErrorToast(null), 5000);
    } finally {
      setSubscribingPlan(null);
    }
  };

  // Currency Verification & Subscription Renewal States
  const [verifiedCurrencyData, setVerifiedCurrencyData] = useState<any>(null);
  const [isVerifyingCurrency, setIsVerifyingCurrency] = useState<boolean>(false);
  const [currencyVerificationToast, setCurrencyVerificationToast] = useState<string | null>(null);

  const handleVerifyCurrency = async () => {
    if (!token || !user) return;
    setIsVerifyingCurrency(true);
    try {
      const res = await fetch('/api/user/verify-currency', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });
      const data = await res.json();
      if (res.ok && data.success && data.data) {
        setVerifiedCurrencyData(data.data);
        if (data.data.coins !== undefined) {
          setCoins(data.data.coins);
        }
        if (data.data.subscriptionStatus && user) {
          setUser({
            ...user,
            coins: data.data.coins,
            plan_type: data.data.planType,
            subscription_status: data.data.subscriptionStatus,
            subscription_end_date: data.data.subscriptionEndDate,
            subscription_start_date: data.data.subscriptionStartDate,
            subscription_plan_id: data.data.subscriptionPlanId
          });
        }
        setCurrencyVerificationToast('تم التحقق بنجاح وتأكيد صحة رصيد العملات والاشتراك من الخادم المركزي.');
      } else {
        setCurrencyVerificationToast(data.error || 'تعذر التحقق من الرصيد والاشتراك.');
      }
    } catch (err) {
      setCurrencyVerificationToast('حدث خطأ في الاتصال أثناء التحقق من الرصيد.');
    } finally {
      setIsVerifyingCurrency(false);
      setTimeout(() => setCurrencyVerificationToast(null), 5000);
    }
  };

  // Multi-Device Management State (Max 3 Devices) & Session Invalidation
  const [userDevices, setUserDevices] = useState<any[]>([]);
  const [loadingDevices, setLoadingDevices] = useState<boolean>(false);
  const [deviceActionMessage, setDeviceActionMessage] = useState<{ text: string; type: 'success' | 'error' }>({ text: '', type: 'success' });
  const [sessionRevokedModal, setSessionRevokedModal] = useState<boolean>(false);
  const [accountDeletedModal, setAccountDeletedModal] = useState<boolean>(false);
  const [accountDeletedMessage, setAccountDeletedMessage] = useState<string>('');

  const handleForceLogout = (reason?: string, modalType?: 'deleted' | 'revoked' | 'expired') => {
    localStorage.removeItem('egs_token');
    localStorage.removeItem('egs_user');
    localStorage.removeItem('egs_chat_sessions');
    localStorage.removeItem('egs_active_exam_id');
    localStorage.removeItem('egs_active_exam_time');
    localStorage.removeItem('egs_active_exam_answers');
    setToken(null);
    setUser(null);
    setProfileName('');
    setActiveSessionId(null);
    setSessions([]);
    setUserDevices([]);
    if (modalType === 'revoked') {
      setCoins(20.0);
      setSessionRevokedModal(true);
    } else {
      setCoins(5.0);
      if (modalType === 'deleted' || reason) {
        setAccountDeletedMessage(reason || 'تم تسجيل الخروج لأن هذا الحساب لم يعد متوفراً أو تم حذفه.');
        setAccountDeletedModal(true);
      }
    }
    setActiveTab(prev => (prev === 'profile' || prev === 'admin' ? 'chat' : prev));
    loadSystemConfig(deviceId, null, true);
    loadNotifications(null, true);
  };

  const handleSessionRevoked = () => {
    handleForceLogout('تم إنهاء الجلسة على هذا الجهاز.', 'revoked');
  };

  const checkAuthError = (resStatus: number, data?: any): boolean => {
    if (resStatus === 401 || (resStatus === 404 && (data?.code === 'user_not_found' || data?.error === 'user_not_found'))) {
      if (data?.code === 'device_session_revoked' || data?.error === 'device_session_revoked' || data?.code === 'device_limit_exceeded') {
        handleForceLogout(data?.message || 'تم تسجيل الخروج من هذا الجهاز.', 'revoked');
        return false;
      }
      if (data?.code === 'user_not_found' || data?.error === 'user_not_found' || data?.message?.includes('غير موجود') || data?.message?.includes('حذف') || data?.error?.includes('غير موجود')) {
        handleForceLogout(data?.message || 'تم إنهاء الجلسة لأن الحساب لم يعد متوفراً أو تم حذفه نهائياً.', 'deleted');
        return false;
      }
      handleForceLogout('انتهت صلاحية الجلسة أو تعذر العثور على الحساب. يرجى تسجيل الدخول مجدداً.', 'deleted');
      return false;
    }
    return true;
  };

  const fetchUserDevices = async () => {
    if (!token) return;
    setLoadingDevices(true);
    try {
      const currentDevId = localStorage.getItem('egs_device_id') || undefined;
      const res = await fetch(`/api/auth/devices?device_id=${currentDevId || ''}`, {
        headers: {
          'Authorization': `Bearer ${token}`,
          'x-device-id': currentDevId || ''
        }
      });
      const data = await res.json();
      if (!res.ok) {
        checkAuthError(res.status, data);
        return;
      }
      if (data.success && data.devices) {
        setUserDevices(data.devices);
      }
    } catch (err) {
      console.error('Failed to fetch user devices:', err);
    } finally {
      setLoadingDevices(false);
    }
  };

  const handleLogoutDevice = async (targetDeviceId: string) => {
    if (!token) return;
    try {
      const currentDevId = localStorage.getItem('egs_device_id') || undefined;
      const res = await fetch(`/api/auth/devices?device_id=${targetDeviceId}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${token}`,
          'x-device-id': currentDevId || ''
        }
      });
      const data = await res.json();
      if (data.success) {
        setDeviceActionMessage({ text: 'تم تسجيل الخروج من الجهاز بنجاح.', type: 'success' });
        fetchUserDevices();
        setTimeout(() => setDeviceActionMessage({ text: '', type: 'success' }), 4000);
      } else {
        setDeviceActionMessage({ text: data.error || 'فشل تسجيل الخروج من الجهاز.', type: 'error' });
      }
    } catch (err: any) {
      setDeviceActionMessage({ text: err.message || 'حدث خطأ غير متوقع.', type: 'error' });
    }
  };

  const handleLogoutAllOtherDevices = async () => {
    if (!token) return;
    try {
      const currentDevId = localStorage.getItem('egs_device_id') || undefined;
      const res = await fetch(`/api/auth/devices?action=logout_all_others`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${token}`,
          'x-device-id': currentDevId || ''
        }
      });
      const data = await res.json();
      if (data.success) {
        setDeviceActionMessage({ text: 'تم تسجيل الخروج من جميع الأجهزة الأخرى بنجاح.', type: 'success' });
        fetchUserDevices();
        setTimeout(() => setDeviceActionMessage({ text: '', type: 'success' }), 4000);
      } else {
        setDeviceActionMessage({ text: data.error || 'فشل تسجيل الخروج من الأجهزة الأخرى.', type: 'error' });
      }
    } catch (err: any) {
      setDeviceActionMessage({ text: err.message || 'حدث خطأ غير متوقع.', type: 'error' });
    }
  };

  const handleResetUserDevices = async (targetUserId: string) => {
    if (!token) return;
    try {
      const res = await fetch('/api/admin/users', {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ id: targetUserId, action: 'reset_devices' })
      });
      const data = await res.json();
      if (data.success) {
        loadAdminUsers();
      }
    } catch (err) {
      console.error('Failed to reset user devices:', err);
    }
  };
  
  // Phase 2 Helper Functions
  const fetchFlashcardDecks = async () => {
    if (!token) return;
    setLoadingDecks(true);
    try {
      const res = await fetch('/api/flashcards', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (!res.ok) {
        checkAuthError(res.status, data);
        return;
      }
      if (data.success) {
        setFlashcardDecks(data.decks || []);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingDecks(false);
    }
  };

  const fetchDueCards = async (deckId: string) => {
    if (!token) return;
    try {
      const res = await fetch(`/api/flashcards/review?deck_id=${deckId}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (!res.ok) {
        checkAuthError(res.status, data);
        return;
      }
      if (data.success) {
        setDeckCards(data.cards || []);
        setCurrentCardIndex(0);
        setIsCardFlipped(false);
      }
    } catch (e) {
      console.error(e);
    }
  };

  const submitCardReview = async (cardId: string, rating: number) => {
    if (!token) return;
    try {
      const res = await fetch('/api/flashcards/review', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ card_id: cardId, rating })
      });
      const data = await res.json();
      if (!res.ok) {
        checkAuthError(res.status, data);
        return;
      }
      if (data.success) {
        if (currentCardIndex < deckCards.length - 1) {
          setIsCardFlipped(false);
          setTimeout(() => {
            setCurrentCardIndex(prev => prev + 1);
          }, 300);
        } else {
          notify('تهانينا! لقد أكملت مراجعة جميع الكروت المستحقة في هذه المجموعة.', 'success');
          setSelectedDeck(null);
          fetchFlashcardDecks();
        }
      }
    } catch (e) {
      console.error(e);
    }
  };

  const fetchSubjectCards = async (subjectName: string) => {
    if (!token) return;
    setLoadingDecks(true);
    try {
      const res = await fetch(`/api/flashcards/subject?subject_name=${encodeURIComponent(subjectName)}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) {
        setSubjectDecks(data.decks || []);
        setSubjectCards(data.cards || []);
        setActiveStackIndex(0);
        setDoneCards([]);
        setIsCardFlipped(false);
        setFlashcardViewMode('grid');
        setRevealedAnswers({});
        setDeckFilter(null);
        setReviewedCardRatings({});
        setSelectedFlashcardSubject(subjectName);
      }
    } catch (e) {
      console.error('Fetch subject cards error:', e);
    } finally {
      setLoadingDecks(false);
    }
  };

  const advancePlayingCard = (targetIndex?: number) => {
    if (isDealingAway) return;
    setIsDealingAway(true);
    setTimeout(() => {
      setIsCardFlipped(false);
      if (targetIndex !== undefined) {
        setActiveStackIndex(targetIndex);
      } else {
        setActiveStackIndex(prev => prev + 1);
      }
      setIsDealingAway(false);
    }, 420);
  };

  const submitSubjectCardReview = async (cardId: string, rating: number, isGridMode: boolean = false) => {
    if (!token) return;
    setReviewingCardId(cardId);
    try {
      const res = await fetch('/api/flashcards/review', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ card_id: cardId, rating })
      });
      let data: any = null;
      try {
        const text = await res.text();
        if (text) {
          data = JSON.parse(text);
        }
      } catch (parseErr) {
        console.error('Failed to parse response from /api/flashcards/review:', parseErr);
      }

      if (!res.ok || !data) {
        if (data) checkAuthError(res.status, data);
        notify((data && data.error) || 'حدث خطأ أثناء حفظ تقييم الاستدعاء', 'error');
        return;
      }
      if (data.success && data.card) {
        const updated = data.card;
        setSubjectCards(prev => prev.map(c => c.id === cardId ? { ...c, box: updated.box, next_review_at: updated.next_review_at } : c));
        setReviewedCardRatings(prev => ({ ...prev, [cardId]: rating }));

        if (isGridMode) {
          // Standard/Grid mode: Keep user in place, immediate visual feedback on card & box level
        } else {
          // Interactive stack mode: record in doneCards and advance smoothly
          const targetCard = subjectCards.find(c => c.id === cardId) || subjectCards[activeStackIndex];
          if (targetCard) {
            setDoneCards(prev => [...prev, { ...targetCard, box: updated.box, next_review_at: updated.next_review_at }]);
          }
          advancePlayingCard();
        }
      }
    } catch (e) {
      console.error('submitSubjectCardReview error:', e);
    } finally {
      setReviewingCardId(null);
    }
  };

  const handleSaveCardEdit = async (cardId: string, question: string, answer: string) => {
    if (!token) return;
    try {
      const res = await fetch('/api/flashcards/card', {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ id: cardId, question, answer })
      });
      const data = await res.json();
      if (data.success) {
        setSubjectCards(prev => prev.map(c => c.id === cardId ? { ...c, question, answer } : c));
        setEditingCard(null);
      } else {
        notify(data.error || 'فشل تعديل الكارت', 'error');
      }
    } catch (e) {
      console.error(e);
    }
  };

  const handleDeleteCard = async (cardId: string) => {
    if (!token || !(await askConfirm('هل أنت متأكد من حذف هذا الكارت؟'))) return;
    try {
      const res = await fetch(`/api/flashcards/card?id=${cardId}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (!res.ok) {
        checkAuthError(res.status, data);
        return;
      }
      if (data.success) {
        setSubjectCards(prev => prev.filter(c => c.id !== cardId));
        setEditingCard(null);
      } else {
        notify(data.error || 'فشل حذف الكارت', 'error');
      }
    } catch (e) {
      console.error(e);
    }
  };

  const handleRenameDeck = async (deckId: string, newTitle: string) => {
    if (!token || !newTitle.trim()) return;
    try {
      const res = await fetch('/api/flashcards', {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ id: deckId, title: newTitle.trim() })
      });
      const data = await res.json();
      if (!res.ok) {
        checkAuthError(res.status, data);
        return;
      }
      if (data.success) {
        setEditingDeck(null);
        fetchFlashcardDecks();
        if (selectedFlashcardSubject) {
          fetchSubjectCards(selectedFlashcardSubject);
        }
      } else {
        notify(data.error || 'فشل إعادة التسمية', 'error');
      }
    } catch (e) {
      console.error(e);
    }
  };

  const handleDeleteDeck = async (deckId: string) => {
    if (!token || !(await askConfirm('هل أنت متأكد من حذف هذه المجموعة بالكامل؟'))) return;
    try {
      const res = await fetch(`/api/flashcards?id=${deckId}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (!res.ok) {
        checkAuthError(res.status, data);
        return;
      }
      if (data.success) {
        fetchFlashcardDecks();
        if (selectedFlashcardSubject) {
          fetchSubjectCards(selectedFlashcardSubject);
        }
      } else {
        notify(data.error || 'فشل حذف المجموعة', 'error');
      }
    } catch (e) {
      console.error(e);
    }
  };

  const openCreatedDeck = async (subject: string, deckId: string | null, cardCount: number) => {
    setShowFlashcardCreateModal(false);
    setActiveTab('flashcards');
    fetchFlashcardDecks();
    await fetchSubjectCards(subject);
    setDeckFilter(deckId);
    notify(`تم إنشاء ${cardCount} ${cardCount > 10 || cardCount < 3 ? 'كارت' : 'كروت'} في ${subject}`, 'success');
  };

  const handleManualCreateDeck = async (subject: string = flashcardSubject) => {
    if (!token || !subject || !manualDeckTitle.trim()) return;
    const validCards = manualCardsList.filter(c => c.question.trim() && c.answer.trim());
    if (validCards.length === 0) {
      notify('يرجى إضافة كارت واحد على الأقل يحتوي على سؤال وإجابة', 'info');
      return;
    }

    setGeneratingDecks(true);
    try {
      const res = await fetch('/api/flashcards', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          subject_name: subject,
          grade_level: user?.grade_level || '1_high',
          title: manualDeckTitle.trim(),
          cards: validCards
        })
      });
      const data = await res.json();
      if (!res.ok) {
        if (!checkAuthError(res.status, data)) return;
        notify(data.error || 'فشل إنشاء الكروت', 'error');
        return;
      }
      if (data.success) {
        setManualDeckTitle('');
        setManualCardsList([{ question: '', answer: '' }]);
        await openCreatedDeck(subject, data.deck?.id ?? null, validCards.length);
      } else {
        notify(data.error || 'فشل إنشاء الكروت', 'error');
      }
    } catch (e) {
      console.error(e);
      notify('تعذر الاتصال بالخادم، حاول مرة أخرى', 'error');
    } finally {
      setGeneratingDecks(false);
    }
  };

  const broadcastCurriculumSync = () => {
    if (typeof window === 'undefined') return;
    try {
      const channel = new BroadcastChannel('egs_curriculum_sync');
      channel.postMessage({ type: 'CURRICULUM_UPDATED', timestamp: Date.now() });
      channel.close();
    } catch (e) {}
    try {
      localStorage.setItem('egs_curriculum_sync_timestamp', Date.now().toString());
    } catch (e) {}
  };

  const fetchCurriculumStructure = async (grade: string, subject: string, force: boolean = false) => {
    if (!grade || !subject) return null;
    const cacheKey = `${grade}_${subject}`;
    if (!force && curriculumStructures[cacheKey]) return curriculumStructures[cacheKey];

    setLoadingStructure(true);
    try {
      const url = `/api/curriculum/structure?grade_level=${encodeURIComponent(grade)}&subject_name=${encodeURIComponent(subject)}${force ? `&t=${Date.now()}` : ''}`;
      const res = await fetch(url, { cache: force ? 'no-store' : 'default' });
      const data = await res.json();
      if (data.success) {
        const structureData = {
          units: data.units || [],
          totalLessons: data.totalLessons || 0,
          hasCurriculum: !!data.hasCurriculum
        };
        setCurriculumStructures(prev => ({
          ...prev,
          [cacheKey]: structureData
        }));
        return structureData;
      }
    } catch (e) {
      console.error('Failed to load curriculum structure:', e);
    } finally {
      setLoadingStructure(false);
    }
    return null;
  };

  const generateFlashcardDeck = async (subject: string = flashcardSubject) => {
    const activeTopic = flashcardTopic.trim() || (selectedFlashcardLesson ? selectedFlashcardLesson.title : '');
    if (!token || !subject || !activeTopic) return;
    setGeneratingDecks(true);
    try {
      const currentGrade = user?.grade_level || chatGrade || '1_high';
      const res = await fetch('/api/flashcards/generate', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          subject_name: subject,
          grade_level: currentGrade,
          topic: activeTopic,
          count: flashcardCount
        })
      });
      let data: any = {};
      const contentType = res.headers.get('content-type') || '';
      if (contentType.includes('application/json')) {
        try {
          data = await res.json();
        } catch {
          data = {};
        }
      }
      if (!res.ok) {
        if (!checkAuthError(res.status, data)) return;
        notify(data?.error || 'فشل توليد الكروت', 'error');
        return;
      }
      if (data.success) {
        syncRemainingCoins(data.remaining_coins);
        setFlashcardTopic('');
        setSelectedFlashcardLesson(null);
        await openCreatedDeck(subject, data.deck?.id ?? null, data.cards?.length || flashcardCount);
      } else {
        notify(data.error || 'فشل توليد الكروت', 'error');
      }
    } catch (e) {
      console.error(e);
      notify('تعذر الاتصال بالخادم، حاول مرة أخرى', 'error');
    } finally {
      setGeneratingDecks(false);
    }
  };

