  // Save edited curriculum Markdown content
  const handleSaveCurriculumEdit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editCurriculumId) return;

    setEditModalLoading(true);
    setEditModalError('');

    try {
      const res = await fetch('/api/admin/curriculum/detail', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          id: editCurriculumId,
          grade_level: editGrade,
          subject_name: editSubject,
          content: editContent
        })
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'فشل حفظ التعديلات.');

      const currId = editCurriculumId;
      const subject = editSubject;
      const pendingCount = data.stats?.pendingEmbeddingCount || 0;

      setEditCurriculumId(null);
      await loadCurriculums();
      loadSystemConfig(undefined, undefined, true);
      setCurriculumStructures({});
      broadcastCurriculumSync();

      if (currId && pendingCount > 0) {
        runProgressiveEmbedding(currId, subject, pendingCount);
      } else {
        fetchCurriculumStructure(editGrade, subject, true);
        notify('تم تحديث محتوى المنهج الدراسي بنجاح.', 'success');
      }
    } catch (err: any) {
      setEditModalError(err.message || 'فشل الحفظ.');
    } finally {
      setEditModalLoading(false);
    }
  };

